/**
 * Confluence Node - Version 1
 * Discriminator: resource=attachment, operation=delete
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Move an attachment to the trash, or permanently delete it */
export type ConfluenceV1AttachmentDeleteParams = {
  resource: 'attachment';
  operation: 'delete';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * The ID of the attachment to delete. Attachment IDs come from the Get Many operation.
 */
    attachmentId: string | Expression<string>;
/**
 * Whether to permanently delete the attachment instead of moving it to trash. This cannot be undone and requires admin permission in the attachment's space.
 * @default false
 */
    purge?: boolean | Expression<boolean>;
};

export type ConfluenceV1AttachmentDeleteNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1AttachmentDeleteParams> & { credentials?: Credentials };
};